  "loc.enterInternetConnectionsAddress": "Als Server die Adresse eures Internet-Anschlusses eintragen (z. B. eure MyFRITZ!-Adresse) – meist per SMS-Befehl laut Anleitung des Trackers.",
  "loc.enterShopAddressesUnder": "Adressen für Läden gibst du unter Listen → Einkaufsliste bearbeiten an – gibt es einen Laden mehrmals, auch mehrere Filialen. Bleibt jemand dort eine Weile, wird der geplante Einkauf abgehakt.",
