  "loc.gpsTracker": "🛰️ GPS-Tracker",
  "loc.guide1": "App <b>„Traccar Client“</b> installieren (App Store bzw. Google Play, kostenlos).",
  "loc.guide2": "In der App bei <b>Geräte-ID</b> (Device identifier) eintragen:",
  "loc.guide3": "Bei <b>Server-URL</b> eintragen:",
  "loc.guide4": "Genauigkeit <b>Mittel</b>, Distanz <b>50 m</b>. Die App sendet dann nur, wenn du dich bewegst – im Stehen nichts. Gibt es bei dir weitere Felder (Intervall, Heartbeat), Heartbeat aus bzw. 0.",
  "loc.guide5": "Standortzugriff erlauben: <b>Immer</b> und <b>Genauer Standort</b> an.",
  "loc.guide6": "Den Schalter <b>Dienst / Tracking</b> einschalten und <b>immer an lassen</b> – fertig. Ab jetzt steuerst du alles in pinn.: „Dauerhaft senden“ an oder aus, „Einmalig senden“ und SOS. Solange „Dauerhaft senden“ aus ist, sieht niemand deinen Standort und pinn. zeichnet keinen Weg auf.",
  "loc.guideIntro": "Ohne weitere App geht „📍 Standort teilen“ direkt in pinn. – dann aber nur, solange pinn. offen ist. Damit der Standort auch bei geschlossenem pinn. und gesperrtem Bildschirm kommt, sendet die kostenlose App „Traccar Client“ ihn direkt an pinn. (ein Traccar-Server ist nicht nötig). Gilt für iPhone und Android gleich.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Dieser Port muss in der FRITZ!Box auf das NAS freigegeben sein, weil der Tracker aus dem Mobilfunknetz kommt.",
