  "loc.setup": "Einrichtung · {famDeviceName}",
  "loc.setupIntro": "Handys brauchen nichts weiter: Jeder kann unter „Mein Standort“ direkt in pinn. teilen. Im Hintergrund (pinn. geschlossen) sendet das Handy mit der kostenlosen App „Traccar Client“ (iPhone und Android) – direkt an pinn., ein Traccar-Server ist dafür nicht nötig. Nur GPS-Tracker mit SIM-Karte (z. B. am Halsband) brauchen den Container „traccar“. Die Standorte bleiben auf eurem NAS.",
