  "settings.calendar.fromFamily#wg": "von der WG · pinn.",
  "settings.calendar.info": "Jedes Profil meldet sich mit seinem eigenen iCloud- oder Google-Konto an und hakt die Kalender daraus an: „Für mich“ sieht nur das eigene Profil, „Familie“ sehen und nutzen alle in eurer Familie. Die anderen sehen dabei nur, über welches Konto ein Familienkalender kommt – unkenntlich gemacht, z. B. m**l@g***l.com. Termine lassen sich wie gewohnt anlegen, bearbeiten, verschieben und offline vormerken und landen direkt in iCloud bzw. Google (und damit auf dem Handy). Abgleich alle 15 Minuten oder mit „Jetzt aktualisieren“. Ohne Konto geht auch ein Kalender nur auf eurem pinn.-Server. Erinnerungen und Tagesübersicht per Push: private Termine nur an dich.",
  "settings.calendar.info#wg": "Jedes Profil meldet sich mit seinem eigenen iCloud- oder Google-Konto an und hakt die Kalender daraus an: „Für mich“ sieht nur das eigene Profil, „WG“ sehen und nutzen alle in eurer WG. Die anderen sehen dabei nur, über welches Konto ein WG-Kalender kommt – unkenntlich gemacht, z. B. m**l@g***l.com. Termine lassen sich wie gewohnt anlegen, bearbeiten, verschieben und offline vormerken und landen direkt in iCloud bzw. Google (und damit auf dem Handy). Abgleich alle 15 Minuten oder mit „Jetzt aktualisieren“. Ohne Konto geht auch ein Kalender nur auf eurem pinn.-Server. Erinnerungen und Tagesübersicht per Push: private Termine nur an dich.",
