  "smart.guide1": "1. Neuer Kurzbefehl „pinn Automatik“:",
  "smart.guide10": "Das Gerät muss pinn. dabei erreichen (WLAN zu Hause oder VPN). Jede Aktion läuft je Aufgabe nur einmal; was schon per Knopf gestartet wurde, startet die Automatik nicht noch einmal.",
  "smart.guide2": "• „Inhalt von URL abrufen“ – den Link oben einfügen",
  "smart.guide3": "• „Wörterbuchwert abrufen“ – Schlüssel „aktionen“",
  "smart.guide4": "• „Wiederholen mit jedem Objekt“, darin:",
  "smart.guide5": "– „Wörterbuchwert abrufen“ – Schlüssel „eingabe“ aus „Wiederholungsobjekt“",
  "smart.guide6": "– „Wörterbuchwert abrufen“ – Schlüssel „kurzbefehl“ aus „Wiederholungsobjekt“",
  "smart.guide7": "– „Kurzbefehl ausführen“ – als Kurzbefehl den Wert „kurzbefehl“, als Eingabe den Wert „eingabe“ wählen",
  "smart.guide8": "2. Tab „Automation“ → „Tageszeit“ – je Uhrzeit oben eine Automation, „Sofort ausführen“ → „pinn Automatik“.",
  "smart.guide9": "3. Tipp: zusätzlich „Ankommen“ (Zuhause) → „pinn Automatik“ – holt Verpasstes nach.",
  "smart.haAddress": "Adresse",
