  "smart.haDevices": "Geräte über Home Assistant: {list}",
  "smart.haIntro": "Der pinn.-Server steuert Home Assistant direkt – Knöpfe funktionieren auf jedem Gerät (auch Android), Automatik und „Beim Abhaken“ laufen ohne Kurzbefehle. Mit einer Status-Entität wartet pinn., bis z. B. der Saugroboter wirklich fertig ist.",
