  "smart.haSearching": "Suche Home Assistant …",
  "smart.haTip1": "Roborock: Gerät „Saugroboter“ anlegen, oben den Roboter (vacuum.…) wählen – pinn. lädt die Räume aus der Karte. Je Aktion „Raumreinigung“ mit Räumen und Modus (Saugen, Saugen & Wischen, Wischen). „Raum der Aufgabe“ nimmt den Raum der Haushalt-Reinigung – die Namen müssen wie in der Roborock-App heißen.",
  "smart.haTip2": "Der Roboter dient zugleich als Status: die nächste Aktion startet erst, wenn er wieder in der Station ist.",
  "smart.haTip3": "Skripte bekommen den Raumnamen als Variable <span class=\"font-mono\">raum</span> – ein Skript kann so alle Räume bedienen.",
