  "smart.haToken": "Langlebiger Zugriffstoken",
  "smart.haTokenHint": "In Home Assistant: unten links auf dein Profil → Reiter „Sicherheit“ → „Langlebige Zugriffstoken“ → „Token erstellen“ und die lange Zeichenkette komplett einfügen. „Bearer“ musst du nicht davorschreiben – das ergänzt pinn. selbst (stört aber auch nicht). Der Token bleibt auf dem Server und wird nie an Geräte geschickt.",
